export function AccountNav() {
  const [open, setOpen] = useState(false);
  return (
    <nav aria-label="Account">
      <button
        type="button"
        aria-expanded={open}
        aria-controls="account-links"
        onClick={() => setOpen((o) => !o)}
      >
        Account
      </button>
      <ul id="account-links" hidden={!open}>
        <li><a href="/settings" aria-current="page">Settings</a></li>
        <li><a href="/billing">Billing</a></li>
      </ul>
    </nav>
  );
}

export function ConfirmDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const ref = useRef<HTMLDialogElement>(null);
  const trigger = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (open && !dialog.open) {
      trigger.current = document.activeElement as HTMLElement | null; // 1. who opened it
      dialog.showModal(); // 2-4. focus inside, inert background, Escape closes
    } else if (!open && dialog.open) {
      dialog.close();
    }
  }, [open]);

  function handleClose() {
    // 5. the browser restores focus itself; if the trigger is gone, choose a target
    const t = trigger.current;
    if (t && !t.isConnected) document.querySelector<HTMLElement>("main h1")?.focus();
    onClose();
  }

  return (
    <dialog ref={ref} onClose={handleClose} aria-labelledby="confirm-title">
      <h2 id="confirm-title">Delete this chat?</h2>
      <button type="button" autoFocus onClick={() => ref.current?.close()}>Cancel</button>
      <button type="button" onClick={() => ref.current?.close()}>Delete</button>
    </dialog>
  );
}

"use client";
export function RouteFocus() {
  const pathname = usePathname();          // next/navigation
  const first = useRef(true);
  useEffect(() => {
    if (first.current) { first.current = false; return; } // don't steal focus on first load
    document.querySelector<HTMLElement>("main h1")?.focus();
  }, [pathname]);
  return null;
}
