export function Chat({ send }: {
  send: (q: string, onDelta: (t: string) => void, signal: AbortSignal) => Promise<void>;
}) {
  const [answer, setAnswer] = useState("");
  const [streaming, setStreaming] = useState(false);
  const [announcement, setAnnouncement] = useState(""); // screen readers only
  const ctrl = useRef<AbortController | null>(null);
  const composer = useRef<HTMLTextAreaElement>(null);

  async function ask(q: string) {
    ctrl.current = new AbortController();
    setAnswer(""); setAnnouncement(""); setStreaming(true);
    let full = "";
    try {
      await send(q, (t) => { full += t; setAnswer(full); }, ctrl.current.signal);
      setAnnouncement(full);                // one announcement, when complete
    } catch {
      setAnnouncement("Response stopped");  // abort or error: said once
    } finally {
      setStreaming(false);
    }
  }

  return (
    <main>
      <div aria-busy={streaming}>{answer}</div>
      <div className="sr-only" aria-live="polite">{announcement}</div>
      {streaming && (
        <button type="button" onClick={() => { ctrl.current?.abort(); composer.current?.focus(); }}>
          Stop
        </button>
      )}
      <textarea ref={composer} aria-label="Message"
        onKeyDown={(e) => { if (e.key === "Enter") ask(e.currentTarget.value); }} />
    </main>
  );
}

/* WebAIM: hidden visually, still read by screen readers */
.sr-only {
  position: absolute; left: -10000px; top: auto;
  width: 1px; height: 1px; overflow: hidden;
}

@media (prefers-reduced-motion: reduce) {
  .typing-cursor { animation: none; }
  .chat-scroll { scroll-behavior: auto; }
}

